class RollingErrorRate {
  constructor(windowMs, bucketCount = 10) {
    this.windowMs = windowMs;
    this.bucketCount = bucketCount;
    this.bucketMs = windowMs / bucketCount;
    this.buckets = Array.from({ length: bucketCount }, () => ({ start: -1, total: 0, errors: 0 }));
  }

  _locate(ts) {
    const slot = Math.floor(ts / this.bucketMs);
    const idx = slot % this.bucketCount;
    const start = slot * this.bucketMs;
    const b = this.buckets[idx];
    if (b.start !== start) { // 轮转：该槽位属于新时间段，旧数据已过期
      b.start = start;
      b.total = 0;
      b.errors = 0;
    }
    return b;
  }

  record(success, ts = Date.now()) {
    const b = this._locate(ts);
    b.total++;
    if (!success) b.errors++;
  }

  _snapshot(now = Date.now()) {
    const minStart = now - this.windowMs;
    let total = 0, errors = 0;
    for (const b of this.buckets) {
      if (b.start >= 0 && b.start + this.bucketMs > minStart) {
        total += b.total;
        errors += b.errors;
      }
    }
    return { total, errors };
  }

  errorRate(now = Date.now()) {
    const { total, errors } = this._snapshot(now);
    return total === 0 ? 0 : errors / total;
  }

  shouldTrip({ minSamples = 20, threshold = 0.5 } = {}, now = Date.now()) {
    const { total, errors } = this._snapshot(now);
    if (total < minSamples) return false; // 小样本不熔断
    return errors / total >= threshold;
  }
}

// ---- 测试 ----
const t0 = 100000;
const r = new RollingErrorRate(1000, 10); // 1 秒窗口、10 个 100ms 桶
for (let i = 0; i < 20; i++) r.record(true, t0 + i * 20);       // 20 成功
for (let i = 0; i < 5; i++) r.record(true, t0 + 600 + i * 10); // 5 成功
for (let i = 0; i < 25; i++) r.record(false, t0 + 700 + i * 5); // 25 失败
console.log('窗口内错误率:', r.errorRate(t0 + 850).toFixed(2)); // 0.50
console.log('熔断判定:', r.shouldTrip({ minSamples: 20, threshold: 0.5 }, t0 + 850)); // true

const r2 = new RollingErrorRate(1000, 10); // 小样本保护验证
r2.record(false, t0); r2.record(false, t0 + 10); r2.record(true, t0 + 20);
console.log('小样本错误率:', r2.errorRate(t0 + 50).toFixed(2), '熔断:', r2.shouldTrip({ minSamples: 20, threshold: 0.5 }, t0 + 50)); // 0.67 false

console.log('窗口滑动后错误率:', r.errorRate(t0 + 2500)); // 0
console.log('滑动后熔断:', r.shouldTrip({}, t0 + 2500));  // false
